// dropos-subdomain-domains.js — node dropos-subdomain-domains.js
const fs=require('fs');const path=require('path');const{execSync}=require('child_process');
const files={"frontend/src/middleware.ts":"// Path: frontend/src/middleware.ts\n// Multi-tenant subdomain routing for DropOS\n// midelymah.droposhq.com → /store/midelymah\n// Also handles custom domains: midelymah.com → /store/midelymah (via DB lookup)\n\nimport { NextResponse } from \"next/server\";\nimport type { NextRequest } from \"next/server\";\n\nconst ROOT_DOMAIN = process.env.NEXT_PUBLIC_ROOT_DOMAIN || \"droposhq.com\";\nconst APP_URL     = process.env.NEXT_PUBLIC_APP_URL     || \"https://droposhq.com\";\n\nexport const config = {\n  matcher: [\n    // Match all paths except static assets and Next internals\n    \"/((?!_next/static|_next/image|favicon.ico|robots.txt|sitemap.xml).*)\",\n  ],\n};\n\nexport async function middleware(req: NextRequest) {\n  const url  = req.nextUrl.clone();\n  const host = req.headers.get(\"host\") || \"\";\n\n  // Strip port for local dev\n  const hostname = host.split(\":\")[0];\n\n  // ── 1. Localhost dev — skip subdomain logic ──────────────────────────────\n  if (hostname === \"localhost\" || hostname === \"127.0.0.1\") {\n    return NextResponse.next();\n  }\n\n  // ── 2. Root domain — pass through normally ───────────────────────────────\n  if (hostname === ROOT_DOMAIN || hostname === `www.${ROOT_DOMAIN}`) {\n    return NextResponse.next();\n  }\n\n  // ── 3. Subdomain of droposhq.com — e.g. midelymah.droposhq.com ──────────\n  if (hostname.endsWith(`.${ROOT_DOMAIN}`)) {\n    const slug = hostname.replace(`.${ROOT_DOMAIN}`, \"\");\n    \n    // Skip Vercel preview deployments (*.vercel.app)\n    if (slug.includes(\"vercel\")) return NextResponse.next();\n    \n    // Rewrite to /store/[slug] preserving path\n    url.pathname = `/store/${slug}${url.pathname === \"/\" ? \"\" : url.pathname}`;\n    return NextResponse.rewrite(url);\n  }\n\n  // ── 4. Custom domain — e.g. midelymah.com ───────────────────────────────\n  // Look up which store owns this domain\n  try {\n    const apiUrl = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\n    const res = await fetch(`${apiUrl}/stores/domain/${encodeURIComponent(hostname)}`, {\n      headers: { \"Content-Type\": \"application/json\" },\n      // Short timeout so we don't slow down every request\n      signal: AbortSignal.timeout(2000),\n    });\n\n    if (res.ok) {\n      const data = await res.json();\n      const slug = data?.data?.slug;\n      if (slug) {\n        url.pathname = `/store/${slug}${url.pathname === \"/\" ? \"\" : url.pathname}`;\n        return NextResponse.rewrite(url);\n      }\n    }\n  } catch {\n    // Custom domain lookup failed — fall through\n  }\n\n  // ── 5. Unknown host — redirect to root ──────────────────────────────────\n  return NextResponse.redirect(new URL(\"/\", APP_URL));\n}\n","frontend/src/app/store/[slug]/page.tsx":"\"use client\";\n\nimport { useState, useEffect } from \"react\";\nimport { useParams, useSearchParams } from \"next/navigation\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { publicApi } from \"../../../lib/api\";\nimport { Package } from \"lucide-react\";\nimport Link from \"next/link\";\nimport { TemplateRenderer } from \"../../../components/store/templates/TemplateRenderer\";\n\nexport default function StorefrontPage() {\n  const { slug } = useParams<{ slug: string }>();\n  const [search,          setSearch]          = useState(\"\");\n  const [debouncedSearch, setDebouncedSearch] = useState(\"\");\n  const [category,        setCategory]        = useState(\"All\");\n  const [sort,            setSort]            = useState(\"newest\");\n\n  useEffect(() => {\n    const t = setTimeout(() => setDebouncedSearch(search), 400);\n    return () => clearTimeout(t);\n  }, [search]);\n\n  const { data: store, isLoading: storeLoading, error } = useQuery({\n    queryKey:  [\"public-store\", slug],\n    queryFn:   () => publicApi.get(`/stores/public/${slug}`).then(r => r.data.data),\n    retry:     3,\n    staleTime: 5 * 60 * 1000,\n    enabled:   !!slug,\n  });\n\n  const { data: productsData, isLoading: productsLoading } = useQuery({\n    queryKey: [\"public-products\", store?.id, debouncedSearch, category, sort],\n    queryFn:  () => publicApi.get(`/products/public/${store.id}`, {\n      params: {\n        search:   debouncedSearch || undefined,\n        category: category !== \"All\" ? category : undefined,\n        sort,\n        limit:    48,\n      },\n    }).then(r => r.data),\n    enabled:   !!store?.id,\n    staleTime: 30 * 1000,\n  });\n\n  const { data: flashSales } = useQuery({\n    queryKey: [\"public-flash-sales\", store?.id],\n    queryFn:  () => publicApi.get(`/stores/${store.id}/flash-sales/active`).then(r => r.data.data || []),\n    enabled:   !!store?.id,\n    staleTime: 60 * 1000,\n  });\n\n  if (storeLoading) return (\n    <div style={{ minHeight: \"100vh\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: \"#fafafa\" }}>\n      <div style={{ textAlign: \"center\" }}>\n        <div style={{ width: 40, height: 40, borderRadius: \"50%\", border: \"3px solid #8B5CF630\", borderTopColor: \"#8B5CF6\", animation: \"spin 0.8s linear infinite\", margin: \"0 auto 16px\" }}/>\n        <p style={{ fontSize: 14, color: \"#888\" }}>Loading store…</p>\n        <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n      </div>\n    </div>\n  );\n\n  if (error || !store) return (\n    <div style={{ minHeight: \"100vh\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: \"#fafafa\", flexDirection: \"column\", gap: 16, padding: 24 }}>\n      <Package size={40} style={{ color: \"#ddd\" }}/>\n      <h1 style={{ fontSize: 22, fontWeight: 800, color: \"#111\", margin: 0 }}>Store Not Found</h1>\n      <p style={{ color: \"#888\", fontSize: 14, textAlign: \"center\", maxWidth: 360 }}>\n        This store doesn't exist or may have been removed.\n      </p>\n      <Link href=\"/\" style={{ padding: \"10px 24px\", borderRadius: 10, background: \"#8B5CF6\", color: \"#fff\", textDecoration: \"none\", fontSize: 14, fontWeight: 600 }}>\n        Go to DropOS\n      </Link>\n    </div>\n  );\n\n  const products   = productsData?.products || productsData?.data || [];\n  const categories = [\"All\", ...new Set(products.map((p: any) => p.category).filter(Boolean))] as string[];\n\n  return (\n    <TemplateRenderer\n      store={store}\n      products={products}\n      categories={categories}\n      search={search}\n      onSearch={setSearch}\n      category={category}\n      onCategory={setCategory}\n      sort={sort}\n      onSort={setSort}\n      isLoading={productsLoading}\n      flashSales={flashSales || []}\n    />\n  );\n}\n","frontend/src/app/dashboard/customize/page.tsx":"\"use client\";\n// Path: frontend/src/app/dashboard/customize/page.tsx\n// Visual template picker — full dedicated page\n\nimport { useState, useEffect } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { TEMPLATES, TemplateConfig } from \"../../../components/store/templates/registry\";\nimport { Check, ExternalLink, Lock, Zap, ChevronRight, X, Eye, Palette } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\n\nconst ROOT_DOMAIN = process.env.NEXT_PUBLIC_ROOT_DOMAIN || \"droposhq.com\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\" };\n\nconst PREVIEW_IMAGES: Record<string,string> = {\n  aurora:   \"https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=640&h=400&fit=crop\",\n  obsidian: \"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=640&h=400&fit=crop\",\n  verdant:  \"https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=640&h=400&fit=crop\",\n  atelier:  \"https://images.unsplash.com/photo-1445205170230-053b83016050?w=640&h=400&fit=crop\",\n  voltage:  \"https://images.unsplash.com/photo-1556821840-3a63f15732ce?w=640&h=400&fit=crop\",\n  ember:    \"https://images.unsplash.com/photo-1509440159596-0249088772ff?w=640&h=400&fit=crop\",\n  nexus:    \"https://images.unsplash.com/photo-1550009158-9ebf69173e03?w=640&h=400&fit=crop\",\n  prism:    \"https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=640&h=400&fit=crop\",\n  velvet:   \"https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=640&h=400&fit=crop\",\n  street:   \"https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=640&h=400&fit=crop\",\n  glow:     \"https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=640&h=400&fit=crop\",\n  terra:    \"https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=640&h=400&fit=crop\",\n  ionic:    \"https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=640&h=400&fit=crop\",\n  artisan:  \"https://images.unsplash.com/photo-1509440159596-0249088772ff?w=640&h=400&fit=crop\",\n  apex:     \"https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=640&h=400&fit=crop\",\n  sage:     \"https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=640&h=400&fit=crop\",\n  diamond:  \"https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=640&h=400&fit=crop\",\n  kodiak:   \"https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=640&h=400&fit=crop\",\n  nova:     \"https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=640&h=400&fit=crop\",\n  dusk:     \"https://images.unsplash.com/photo-1566073771259-6a8506099945?w=640&h=400&fit=crop\",\n  kids:     \"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=640&h=400&fit=crop\",\n};\n\nconst TIER_COLORS: Record<string,string> = {\n  free:     \"#10B981\",\n  pro:      \"#8B5CF6\",\n  advanced: \"#F59E0B\",\n};\n\nexport default function CustomizePage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const { user } = useAuthStore();\n  const qc = useQueryClient();\n\n  const tk = {\n    bg:     isDark ? \"#06040D\" : \"#F4F2FB\",\n    card:   isDark ? \"#16122A\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.08)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.03)\",\n  };\n\n  const storeId = user?.stores?.[0]?.id;\n  const storeSlug = user?.stores?.[0]?.slug;\n  const userPlan = user?.subscription?.plan?.toLowerCase() || \"free\";\n\n  const { data: store } = useQuery({\n    queryKey: [\"store-detail\", storeId],\n    queryFn:  () => api.get(`/stores/${storeId}`).then(r => r.data.data),\n    enabled:  !!storeId,\n  });\n\n  const [activeTheme,   setActiveTheme]   = useState(store?.theme || store?.templateId || \"aurora\");\n  const [activeColor,   setActiveColor]   = useState(store?.brandColor || \"#6B35E8\");\n  const [previewOpen,   setPreviewOpen]   = useState<TemplateConfig|null>(null);\n  const [filterTier,    setFilterTier]    = useState<string>(\"all\");\n  const [filterNiche,   setFilterNiche]   = useState<string>(\"all\");\n  const [saving,        setSaving]        = useState(false);\n  const [saved,         setSaved]         = useState(false);\n\n  useEffect(() => {\n    if (store) {\n      setActiveTheme(store.theme || store.templateId || \"aurora\");\n      setActiveColor(store.brandColor || \"#6B35E8\");\n    }\n  }, [store]);\n\n  const planCanUse = (tier: string) => {\n    if (tier === \"free\") return true;\n    if (tier === \"pro\" && [\"pro\",\"growth\",\"advanced\"].includes(userPlan)) return true;\n    if (tier === \"advanced\" && [\"advanced\",\"pro\"].includes(userPlan)) return true;\n    return false;\n  };\n\n  async function applyTheme(templateId: string) {\n    if (!storeId) return;\n    setSaving(true);\n    try {\n      await api.put(`/stores/${storeId}`, { theme: templateId, brandColor: activeColor });\n      setActiveTheme(templateId);\n      setSaved(true);\n      qc.invalidateQueries({ queryKey: [\"store-detail\", storeId] });\n      toast.success(`Template applied!`);\n      setTimeout(() => setSaved(false), 2000);\n    } catch {\n      toast.error(\"Failed to apply template\");\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  async function saveColor() {\n    if (!storeId) return;\n    try {\n      await api.put(`/stores/${storeId}`, { brandColor: activeColor, theme: activeTheme });\n      toast.success(\"Brand color saved!\");\n      qc.invalidateQueries({ queryKey: [\"store-detail\", storeId] });\n    } catch {\n      toast.error(\"Failed to save\");\n    }\n  }\n\n  const niches = [\"all\", ...new Set(TEMPLATES.map(t => t.niche).filter(Boolean))];\n  const filtered = TEMPLATES.filter(t => {\n    if (filterTier !== \"all\" && t.tier !== filterTier) return false;\n    if (filterNiche !== \"all\" && t.niche !== filterNiche) return false;\n    return true;\n  });\n\n  return (\n    <div style={{ maxWidth: 1200, margin: \"0 auto\" }}>\n\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}\n        style={{ display: \"flex\", alignItems: \"flex-start\", justifyContent: \"space-between\", marginBottom: 28, flexWrap: \"wrap\", gap: 12 }}>\n        <div>\n          <h1 style={{ fontSize: 22, fontWeight: 900, letterSpacing: \"-0.04em\", color: tk.text, margin: \"0 0 4px\" }}>\n            Customize Store\n          </h1>\n          <p style={{ fontSize: 13, color: tk.muted, margin: 0 }}>\n            Choose a template, pick your brand color, then preview and apply.\n          </p>\n        </div>\n        <div style={{ display: \"flex\", gap: 10, alignItems: \"center\" }}>\n          {storeSlug && (\n            <a href={`//${storeSlug}.${ROOT_DOMAIN}`} target=\"_blank\" rel=\"noopener noreferrer\"\n              style={{ display: \"flex\", alignItems: \"center\", gap: 6, padding: \"8px 16px\", borderRadius: 10, border: `1px solid ${tk.border}`, color: tk.muted, fontSize: 13, fontWeight: 600, textDecoration: \"none\", background: tk.faint }}>\n              <ExternalLink size={13}/> Preview Store\n            </a>\n          )}\n        </div>\n      </motion.div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 280px\", gap: 20, alignItems: \"start\" }}>\n\n        {/* Left — Template grid */}\n        <div>\n          {/* Filters */}\n          <div style={{ display: \"flex\", gap: 8, marginBottom: 20, flexWrap: \"wrap\", alignItems: \"center\" }}>\n            <span style={{ fontSize: 12, color: tk.muted, fontWeight: 600, marginRight: 4 }}>Filter:</span>\n            {[\"all\",\"free\",\"pro\",\"advanced\"].map(t => (\n              <button key={t} onClick={() => setFilterTier(t)}\n                style={{ padding: \"6px 14px\", borderRadius: 99, fontSize: 12, fontWeight: 600, cursor: \"pointer\", border: `1px solid ${filterTier===t?V.v400:tk.border}`, background: filterTier===t?`${V.v400}15`:\"transparent\", color: filterTier===t?V.v400:tk.muted, fontFamily: \"inherit\", transition: \"all 0.15s\" }}>\n                {t === \"all\" ? \"All\" : t.charAt(0).toUpperCase()+t.slice(1)}\n              </button>\n            ))}\n            <div style={{ width: 1, height: 20, background: tk.border, margin: \"0 4px\" }}/>\n            {niches.slice(0,6).map(n => (\n              <button key={n} onClick={() => setFilterNiche(n)}\n                style={{ padding: \"6px 14px\", borderRadius: 99, fontSize: 12, fontWeight: 600, cursor: \"pointer\", border: `1px solid ${filterNiche===n?V.v400:tk.border}`, background: filterNiche===n?`${V.v400}15`:\"transparent\", color: filterNiche===n?V.v400:tk.muted, fontFamily: \"inherit\", transition: \"all 0.15s\" }}>\n                {n === \"all\" ? \"All Niches\" : n}\n              </button>\n            ))}\n          </div>\n\n          {/* Grid */}\n          <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(auto-fill,minmax(280px,1fr))\", gap: 16 }}>\n            {filtered.map((t, i) => {\n              const isActive  = activeTheme === t.id;\n              const canUse    = planCanUse(t.tier);\n              const img       = PREVIEW_IMAGES[t.id] || PREVIEW_IMAGES.aurora;\n              return (\n                <motion.div key={t.id} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}\n                  style={{ borderRadius: 16, overflow: \"hidden\", border: `2px solid ${isActive ? V.v400 : tk.border}`, background: tk.card, cursor: canUse ? \"pointer\" : \"default\", position: \"relative\", transition: \"all 0.2s\", boxShadow: isActive ? `0 0 0 4px ${V.v400}20` : \"none\" }}\n                  whileHover={canUse ? { scale: 1.02, y: -2 } : {}}\n                  onClick={() => canUse && setPreviewOpen(t)}>\n\n                  {/* Thumbnail */}\n                  <div style={{ position: \"relative\", aspectRatio: \"16/9\", overflow: \"hidden\", background: \"#f0f0f0\" }}>\n                    <img src={img} alt={t.name} style={{ width: \"100%\", height: \"100%\", objectFit: \"cover\", filter: !canUse ? \"grayscale(1) brightness(0.6)\" : \"none\", transition: \"transform 0.4s\" }}/>\n                    {/* Overlay on hover */}\n                    <div style={{ position: \"absolute\", inset: 0, background: \"rgba(0,0,0,0)\", transition: \"background 0.2s\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 8 }}\n                      className=\"template-hover-overlay\">\n                      {canUse && (\n                        <div style={{ display: \"flex\", gap: 8 }}>\n                          <button onClick={e => { e.stopPropagation(); setPreviewOpen(t); }}\n                            style={{ padding: \"8px 16px\", borderRadius: 8, background: \"rgba(255,255,255,0.95)\", border: \"none\", cursor: \"pointer\", fontSize: 12, fontWeight: 700, display: \"flex\", alignItems: \"center\", gap: 6, opacity: 0, transition: \"opacity 0.2s\" }}\n                            className=\"preview-btn\">\n                            <Eye size={12}/> Preview\n                          </button>\n                        </div>\n                      )}\n                    </div>\n                    {/* Active badge */}\n                    {isActive && (\n                      <div style={{ position: \"absolute\", top: 10, left: 10, background: V.v400, borderRadius: 99, padding: \"4px 10px\", display: \"flex\", alignItems: \"center\", gap: 4 }}>\n                        <Check size={10} color=\"#fff\"/>\n                        <span style={{ fontSize: 10, color: \"#fff\", fontWeight: 700 }}>Active</span>\n                      </div>\n                    )}\n                    {/* Lock */}\n                    {!canUse && (\n                      <div style={{ position: \"absolute\", inset: 0, display: \"flex\", flexDirection: \"column\", alignItems: \"center\", justifyContent: \"center\", background: \"rgba(0,0,0,0.6)\" }}>\n                        <Lock size={20} color=\"#fff\" style={{ marginBottom: 6 }}/>\n                        <span style={{ fontSize: 11, color: \"#fff\", fontWeight: 700, textTransform: \"uppercase\", letterSpacing: \"0.08em\" }}>\n                          {t.tier.charAt(0).toUpperCase()+t.tier.slice(1)} Plan\n                        </span>\n                        <Link href=\"/dashboard/billing\" onClick={e => e.stopPropagation()}\n                          style={{ marginTop: 8, padding: \"5px 14px\", borderRadius: 99, background: V.v400, color: \"#fff\", fontSize: 11, fontWeight: 700, textDecoration: \"none\" }}>\n                          Upgrade →\n                        </Link>\n                      </div>\n                    )}\n                    {/* Tier badge */}\n                    <div style={{ position: \"absolute\", top: 10, right: 10, background: TIER_COLORS[t.tier] || \"#888\", borderRadius: 99, padding: \"3px 8px\" }}>\n                      <span style={{ fontSize: 9, color: \"#fff\", fontWeight: 700, textTransform: \"uppercase\", letterSpacing: \"0.08em\" }}>{t.tier}</span>\n                    </div>\n                  </div>\n\n                  {/* Info */}\n                  <div style={{ padding: \"14px 16px 16px\" }}>\n                    <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"flex-start\", marginBottom: 4 }}>\n                      <p style={{ fontSize: 14, fontWeight: 800, color: tk.text, margin: 0 }}>{t.name}</p>\n                      <span style={{ fontSize: 10, color: tk.muted, background: tk.faint, border: `1px solid ${tk.border}`, borderRadius: 4, padding: \"2px 6px\", whiteSpace: \"nowrap\" }}>\n                        {t.niche}\n                      </span>\n                    </div>\n                    <p style={{ fontSize: 12, color: tk.muted, margin: \"0 0 12px\", lineHeight: 1.5 }}>{t.description?.slice(0,80)}…</p>\n                    <div style={{ display: \"flex\", gap: 8 }}>\n                      {canUse && !isActive && (\n                        <button onClick={e => { e.stopPropagation(); applyTheme(t.id); }}\n                          style={{ flex: 1, padding: \"8px 0\", borderRadius: 8, background: `linear-gradient(135deg,${V.v500},${V.v400})`, border: \"none\", color: \"#fff\", fontSize: 12, fontWeight: 700, cursor: \"pointer\", fontFamily: \"inherit\" }}>\n                          Apply Template\n                        </button>\n                      )}\n                      {isActive && (\n                        <div style={{ flex: 1, padding: \"8px 0\", borderRadius: 8, background: `${V.v400}12`, border: `1px solid ${V.v400}30`, color: V.v400, fontSize: 12, fontWeight: 700, textAlign: \"center\" }}>\n                          ✓ Currently Active\n                        </div>\n                      )}\n                      {canUse && (\n                        <button onClick={e => { e.stopPropagation(); setPreviewOpen(t); }}\n                          style={{ padding: \"8px 12px\", borderRadius: 8, border: `1px solid ${tk.border}`, background: \"transparent\", color: tk.muted, fontSize: 12, cursor: \"pointer\", fontFamily: \"inherit\", display: \"flex\", alignItems: \"center\", gap: 4 }}>\n                          <Eye size={11}/> Preview\n                        </button>\n                      )}\n                    </div>\n                  </div>\n                </motion.div>\n              );\n            })}\n          </div>\n        </div>\n\n        {/* Right — Brand panel */}\n        <div style={{ position: \"sticky\", top: 20 }}>\n          <div style={{ borderRadius: 18, background: tk.card, border: `1px solid ${tk.border}`, overflow: \"hidden\" }}>\n            <div style={{ padding: \"16px 18px\", borderBottom: `1px solid ${tk.border}` }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                <Palette size={14} color={V.v400}/>\n                <span style={{ fontSize: 13, fontWeight: 800, color: tk.text }}>Brand Settings</span>\n              </div>\n            </div>\n\n            <div style={{ padding: \"18px\" }}>\n              {/* Active template display */}\n              <div style={{ marginBottom: 20 }}>\n                <p style={{ fontSize: 11, color: tk.muted, fontWeight: 600, marginBottom: 8, textTransform: \"uppercase\", letterSpacing: \"0.06em\" }}>Active Template</p>\n                <div style={{ padding: \"10px 12px\", borderRadius: 10, background: `${V.v400}10`, border: `1px solid ${V.v400}20`, display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\" }}>\n                  <div>\n                    <p style={{ fontSize: 13, fontWeight: 700, color: V.v400, margin: 0 }}>\n                      {TEMPLATES.find(t => t.id === activeTheme)?.name || activeTheme}\n                    </p>\n                    <p style={{ fontSize: 11, color: tk.muted, margin: 0 }}>\n                      {TEMPLATES.find(t => t.id === activeTheme)?.niche}\n                    </p>\n                  </div>\n                  <div style={{ fontSize: 20 }}>{TEMPLATES.find(t => t.id === activeTheme)?.preview || \"🎨\"}</div>\n                </div>\n              </div>\n\n              {/* Color picker */}\n              <div style={{ marginBottom: 20 }}>\n                <p style={{ fontSize: 11, color: tk.muted, fontWeight: 600, marginBottom: 8, textTransform: \"uppercase\", letterSpacing: \"0.06em\" }}>Brand Color</p>\n                <div style={{ display: \"flex\", gap: 8, alignItems: \"center\" }}>\n                  <input type=\"color\" value={activeColor} onChange={e => setActiveColor(e.target.value)}\n                    style={{ width: 44, height: 44, borderRadius: 10, border: `2px solid ${tk.border}`, cursor: \"pointer\", padding: 2, background: \"transparent\" }}/>\n                  <input type=\"text\" value={activeColor} onChange={e => setActiveColor(e.target.value)}\n                    style={{ flex: 1, padding: \"10px 12px\", borderRadius: 10, border: `1px solid ${tk.border}`, background: isDark ? \"rgba(255,255,255,0.04)\" : \"#f9fafb\", color: tk.text, fontSize: 13, outline: \"none\", fontFamily: \"inherit\" }}/>\n                </div>\n                {/* Preset colors */}\n                <div style={{ display: \"flex\", gap: 6, marginTop: 10, flexWrap: \"wrap\" }}>\n                  {[\"#6B35E8\",\"#E8547A\",\"#C4782A\",\"#00D4FF\",\"#39FF14\",\"#D4AF37\",\"#8B5E3C\",\"#BF5AF2\",\"#FF3B00\",\"#5B7B5C\"].map(c => (\n                    <button key={c} onClick={() => setActiveColor(c)}\n                      style={{ width: 24, height: 24, borderRadius: \"50%\", background: c, border: `2px solid ${activeColor === c ? tk.text : \"transparent\"}`, cursor: \"pointer\", transition: \"transform 0.15s\" }}/>\n                  ))}\n                </div>\n                <button onClick={saveColor}\n                  style={{ width: \"100%\", marginTop: 12, padding: \"10px 0\", borderRadius: 10, background: `linear-gradient(135deg,${V.v500},${V.v400})`, border: \"none\", color: \"#fff\", fontSize: 13, fontWeight: 700, cursor: \"pointer\", fontFamily: \"inherit\" }}>\n                  Save Brand Color\n                </button>\n              </div>\n\n              {/* Quick links */}\n              <div style={{ borderTop: `1px solid ${tk.border}`, paddingTop: 16 }}>\n                <p style={{ fontSize: 11, color: tk.muted, fontWeight: 600, marginBottom: 10, textTransform: \"uppercase\", letterSpacing: \"0.06em\" }}>Store Links</p>\n                {[\n                  { label: \"Domain Settings\", href: \"/dashboard/domains\", icon: \"🌐\" },\n                  { label: \"View Live Store\", href: `//${storeSlug}.${ROOT_DOMAIN}`, icon: \"↗\", external: true },\n                  { label: \"Manage Products\", href: \"/dashboard/products\", icon: \"📦\" },\n                ].map(l => (\n                  <a key={l.label} href={l.href} target={l.external?\"_blank\":undefined} rel={l.external?\"noopener noreferrer\":undefined}\n                    style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"9px 12px\", borderRadius: 9, border: `1px solid ${tk.border}`, background: \"transparent\", marginBottom: 6, textDecoration: \"none\", color: tk.text, fontSize: 13, fontWeight: 500, transition: \"background 0.15s\" }}\n                    onMouseEnter={e=>(e.currentTarget.style.background=tk.faint)}\n                    onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n                    <span style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                      <span>{l.icon}</span>{l.label}\n                    </span>\n                    <ChevronRight size={12} color={tk.muted}/>\n                  </a>\n                ))}\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      {/* Preview modal */}\n      <AnimatePresence>\n        {previewOpen && (\n          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}\n            style={{ position: \"fixed\", inset: 0, background: \"rgba(0,0,0,0.85)\", zIndex: 200, display: \"flex\", flexDirection: \"column\", backdropFilter: \"blur(8px)\" }}>\n            {/* Modal nav */}\n            <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"14px 20px\", background: isDark ? \"#0F0A1E\" : \"#fff\", borderBottom: `1px solid ${tk.border}`, flexShrink: 0 }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 14 }}>\n                <span style={{ fontSize: 22 }}>{previewOpen.preview}</span>\n                <div>\n                  <p style={{ fontSize: 15, fontWeight: 800, color: tk.text, margin: 0 }}>{previewOpen.name}</p>\n                  <p style={{ fontSize: 12, color: tk.muted, margin: 0 }}>{previewOpen.niche} · {previewOpen.mood}</p>\n                </div>\n                <div style={{ background: TIER_COLORS[previewOpen.tier], borderRadius: 99, padding: \"3px 10px\" }}>\n                  <span style={{ fontSize: 10, color: \"#fff\", fontWeight: 700, textTransform: \"uppercase\" }}>{previewOpen.tier}</span>\n                </div>\n              </div>\n              <div style={{ display: \"flex\", gap: 10, alignItems: \"center\" }}>\n                {planCanUse(previewOpen.tier) && activeTheme !== previewOpen.id && (\n                  <button onClick={() => { applyTheme(previewOpen.id); setPreviewOpen(null); }}\n                    style={{ padding: \"9px 20px\", borderRadius: 10, background: `linear-gradient(135deg,${V.v500},${V.v400})`, border: \"none\", color: \"#fff\", fontSize: 13, fontWeight: 700, cursor: \"pointer\", fontFamily: \"inherit\", display: \"flex\", alignItems: \"center\", gap: 6 }}>\n                    <Zap size={13}/> Apply This Template\n                  </button>\n                )}\n                {activeTheme === previewOpen.id && (\n                  <div style={{ padding: \"9px 20px\", borderRadius: 10, background: `${V.v400}15`, color: V.v400, fontSize: 13, fontWeight: 700, display: \"flex\", alignItems: \"center\", gap: 6 }}>\n                    <Check size={13}/> Active\n                  </div>\n                )}\n                <button onClick={() => setPreviewOpen(null)}\n                  style={{ width: 36, height: 36, borderRadius: 10, border: `1px solid ${tk.border}`, background: \"transparent\", cursor: \"pointer\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", color: tk.muted }}>\n                  <X size={16}/>\n                </button>\n              </div>\n            </div>\n\n            {/* Preview image / iframe */}\n            <div style={{ flex: 1, overflow: \"hidden\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", padding: 20 }}>\n              <div style={{ width: \"100%\", maxWidth: 1100, height: \"100%\", borderRadius: 16, overflow: \"hidden\", boxShadow: \"0 32px 80px rgba(0,0,0,0.4)\", background: \"#f0f0f0\" }}>\n                {/* Show preview image for now — iframe would need real store URL */}\n                <img src={PREVIEW_IMAGES[previewOpen.id] || PREVIEW_IMAGES.aurora} alt={previewOpen.name}\n                  style={{ width: \"100%\", height: \"100%\", objectFit: \"cover\" }}/>\n              </div>\n            </div>\n\n            <p style={{ textAlign: \"center\", fontSize: 12, color: \"rgba(255,255,255,0.3)\", padding: \"10px 0 16px\" }}>\n              Apply this template to see it live on your store →{\" \"}\n              {storeSlug && <a href={`//${storeSlug}.${ROOT_DOMAIN}`} target=\"_blank\" rel=\"noopener noreferrer\" style={{ color: V.v400, textDecoration: \"none\" }}>{storeSlug}.{ROOT_DOMAIN}</a>}\n            </p>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        .template-hover-overlay:hover { background: rgba(0,0,0,0.3) !important; }\n        .template-hover-overlay:hover .preview-btn { opacity: 1 !important; }\n        @media(max-width:900px){\n          [style*=\"grid-template-columns: 1fr 280px\"] { grid-template-columns: 1fr !important; }\n          [style*=\"position: sticky\"] { position: relative !important; }\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/domains/page.tsx":"\"use client\";\n// Path: frontend/src/app/dashboard/domains/page.tsx\n\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Globe, Check, X, ExternalLink, Copy, AlertCircle, Search, Loader2, CheckCircle, Clock } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst ROOT_DOMAIN  = process.env.NEXT_PUBLIC_ROOT_DOMAIN || \"droposhq.com\";\nconst VERCEL_IP    = \"76.76.21.21\";\nconst VERCEL_CNAME = \"cname.vercel-dns.com\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\" };\n\nexport default function DomainsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const { user } = useAuthStore();\n  const qc = useQueryClient();\n\n  const tk = {\n    card:   isDark ? \"#16122A\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.08)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.03)\",\n    green:  \"#10B981\", amber: \"#F59E0B\", red: \"#EF4444\",\n  };\n\n  const storeId   = user?.stores?.[0]?.id;\n  const storeSlug = user?.stores?.[0]?.slug;\n  const freeSubdomain = `${storeSlug}.${ROOT_DOMAIN}`;\n\n  const [customDomain, setCustomDomain]   = useState(\"\");\n  const [domainSearch, setDomainSearch]   = useState(\"\");\n  const [searchResults, setSearchResults] = useState<any[]>([]);\n  const [searching,    setSearching]      = useState(false);\n\n  const { data: store } = useQuery({\n    queryKey: [\"store-domains\", storeId],\n    queryFn:  () => api.get(`/stores/${storeId}`).then(r => r.data.data),\n    enabled:  !!storeId,\n  });\n\n  const addDomainMut = useMutation({\n    mutationFn: (domain: string) => api.post(`/stores/${storeId}/custom-domain`, { domain }),\n    onSuccess: () => {\n      toast.success(\"Custom domain added! Configure your DNS records below.\");\n      qc.invalidateQueries({ queryKey: [\"store-domains\", storeId] });\n      setCustomDomain(\"\");\n    },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed to add domain\"),\n  });\n\n  const removeDomainMut = useMutation({\n    mutationFn: (domain: string) => api.delete(`/stores/${storeId}/custom-domain`, { data: { domain } }),\n    onSuccess: () => {\n      toast.success(\"Domain removed\");\n      qc.invalidateQueries({ queryKey: [\"store-domains\", storeId] });\n    },\n    onError: () => toast.error(\"Failed to remove domain\"),\n  });\n\n  const verifyMut = useMutation({\n    mutationFn: (domain: string) => api.post(`/stores/${storeId}/custom-domain/verify`, { domain }),\n    onSuccess: (res) => {\n      if (res.data.data?.verified) toast.success(\"Domain verified! ✅\");\n      else toast.error(\"DNS not propagated yet — try again in a few minutes.\");\n      qc.invalidateQueries({ queryKey: [\"store-domains\", storeId] });\n    },\n    onError: () => toast.error(\"Verification failed\"),\n  });\n\n  async function searchDomains() {\n    if (!domainSearch.trim()) return;\n    setSearching(true);\n    // Whogohost / Namecheap check — we show suggestions\n    const base = domainSearch.toLowerCase().replace(/[^a-z0-9-]/g, \"\");\n    const tlds  = [\".com\", \".com.ng\", \".ng\", \".store\", \".shop\", \".co\"];\n    // Simulate check (in production, hit a domain availability API)\n    await new Promise(r => setTimeout(r, 800));\n    setSearchResults(tlds.map((tld, i) => ({\n      domain:     `${base}${tld}`,\n      available:  Math.random() > 0.3,\n      price:      tld === \".com\" ? \"₦8,500/yr\" : tld === \".com.ng\" ? \"₦12,000/yr\" : tld === \".ng\" ? \"₦25,000/yr\" : \"₦6,500/yr\",\n      registrar:  \"https://whogohost.com\",\n    })));\n    setSearching(false);\n  }\n\n  const customDomains: string[] = store?.customDomains || (store?.customDomain ? [store.customDomain] : []);\n\n  function copy(text: string) {\n    navigator.clipboard.writeText(text);\n    toast.success(\"Copied!\");\n  }\n\n  return (\n    <div style={{ maxWidth: 860, margin: \"0 auto\" }}>\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: 28 }}>\n        <h1 style={{ fontSize: 22, fontWeight: 900, letterSpacing: \"-0.04em\", color: tk.text, margin: \"0 0 4px\" }}>Domains</h1>\n        <p style={{ fontSize: 13, color: tk.muted, margin: 0 }}>Manage your store's web address.</p>\n      </motion.div>\n\n      {/* Free subdomain */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}\n        style={{ borderRadius: 18, background: tk.card, border: `1px solid ${tk.border}`, padding: \"20px 24px\", marginBottom: 16 }}>\n        <div style={{ display: \"flex\", alignItems: \"flex-start\", justifyContent: \"space-between\", flexWrap: \"wrap\", gap: 12 }}>\n          <div>\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 6 }}>\n              <div style={{ width: 8, height: 8, borderRadius: \"50%\", background: tk.green }}/>\n              <span style={{ fontSize: 12, fontWeight: 700, color: tk.green }}>Active — Free Subdomain</span>\n            </div>\n            <p style={{ fontSize: 18, fontWeight: 800, color: tk.text, margin: \"0 0 4px\", letterSpacing: \"-0.02em\" }}>\n              {freeSubdomain}\n            </p>\n            <p style={{ fontSize: 12, color: tk.muted, margin: 0 }}>\n              Included with every DropOS store. No setup required.\n            </p>\n          </div>\n          <div style={{ display: \"flex\", gap: 8 }}>\n            <button onClick={() => copy(freeSubdomain)}\n              style={{ padding: \"8px 14px\", borderRadius: 9, border: `1px solid ${tk.border}`, background: \"transparent\", color: tk.muted, fontSize: 12, cursor: \"pointer\", fontFamily: \"inherit\", display: \"flex\", alignItems: \"center\", gap: 6 }}>\n              <Copy size={12}/> Copy\n            </button>\n            <a href={`https://${freeSubdomain}`} target=\"_blank\" rel=\"noopener noreferrer\"\n              style={{ padding: \"8px 14px\", borderRadius: 9, border: `1px solid ${tk.border}`, background: `${V.v400}10`, color: V.v400, fontSize: 12, cursor: \"pointer\", fontFamily: \"inherit\", display: \"flex\", alignItems: \"center\", gap: 6, textDecoration: \"none\", fontWeight: 600 }}>\n              <ExternalLink size={12}/> Visit\n            </a>\n          </div>\n        </div>\n      </motion.div>\n\n      {/* Add custom domain */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}\n        style={{ borderRadius: 18, background: tk.card, border: `1px solid ${tk.border}`, padding: \"20px 24px\", marginBottom: 16 }}>\n        <h3 style={{ fontSize: 15, fontWeight: 800, color: tk.text, margin: \"0 0 4px\" }}>Connect a Custom Domain</h3>\n        <p style={{ fontSize: 13, color: tk.muted, margin: \"0 0 16px\" }}>Already own a domain? Connect it to your store.</p>\n\n        <div style={{ display: \"flex\", gap: 10 }}>\n          <input value={customDomain} onChange={e => setCustomDomain(e.target.value.toLowerCase())}\n            placeholder=\"e.g. mymshop.com\"\n            onKeyDown={e => e.key === \"Enter\" && customDomain && addDomainMut.mutate(customDomain)}\n            style={{ flex: 1, padding: \"11px 14px\", borderRadius: 11, border: `1px solid ${tk.border}`, background: isDark ? \"rgba(255,255,255,0.04)\" : \"#f9fafb\", color: tk.text, fontSize: 14, outline: \"none\", fontFamily: \"inherit\" }}/>\n          <button onClick={() => customDomain && addDomainMut.mutate(customDomain)}\n            disabled={addDomainMut.isPending || !customDomain}\n            style={{ padding: \"11px 20px\", borderRadius: 11, background: `linear-gradient(135deg,${V.v500},${V.v400})`, border: \"none\", color: \"#fff\", fontSize: 13, fontWeight: 700, cursor: addDomainMut.isPending||!customDomain ? \"not-allowed\" : \"pointer\", fontFamily: \"inherit\", display: \"flex\", alignItems: \"center\", gap: 6, opacity: !customDomain ? 0.5 : 1 }}>\n            {addDomainMut.isPending ? <Loader2 size={13} style={{ animation: \"spin 1s linear infinite\" }}/> : <Globe size={13}/>}\n            Connect\n          </button>\n        </div>\n\n        {/* Existing custom domains */}\n        {customDomains.length > 0 && (\n          <div style={{ marginTop: 16, display: \"flex\", flexDirection: \"column\", gap: 10 }}>\n            {customDomains.map((domain: string) => {\n              const isVerified = store?.verifiedDomains?.includes(domain);\n              return (\n                <div key={domain} style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"12px 16px\", borderRadius: 11, background: tk.faint, border: `1px solid ${tk.border}`, flexWrap: \"wrap\", gap: 10 }}>\n                  <div style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n                    {isVerified\n                      ? <CheckCircle size={16} color={tk.green}/>\n                      : <Clock size={16} color={tk.amber}/>\n                    }\n                    <div>\n                      <p style={{ fontSize: 14, fontWeight: 700, color: tk.text, margin: 0 }}>{domain}</p>\n                      <p style={{ fontSize: 11, color: isVerified ? tk.green : tk.amber, margin: 0 }}>\n                        {isVerified ? \"Active & verified\" : \"Pending DNS verification\"}\n                      </p>\n                    </div>\n                  </div>\n                  <div style={{ display: \"flex\", gap: 8 }}>\n                    {!isVerified && (\n                      <button onClick={() => verifyMut.mutate(domain)}\n                        disabled={verifyMut.isPending}\n                        style={{ padding: \"6px 14px\", borderRadius: 8, border: `1px solid ${tk.amber}40`, background: `${tk.amber}10`, color: tk.amber, fontSize: 12, fontWeight: 600, cursor: \"pointer\", fontFamily: \"inherit\" }}>\n                        Verify DNS\n                      </button>\n                    )}\n                    <a href={`https://${domain}`} target=\"_blank\" rel=\"noopener noreferrer\"\n                      style={{ padding: \"6px 12px\", borderRadius: 8, border: `1px solid ${tk.border}`, background: \"transparent\", color: tk.muted, fontSize: 12, textDecoration: \"none\", display: \"flex\", alignItems: \"center\", gap: 4 }}>\n                      <ExternalLink size={11}/>\n                    </a>\n                    <button onClick={() => removeDomainMut.mutate(domain)}\n                      style={{ padding: \"6px 12px\", borderRadius: 8, border: `1px solid rgba(239,68,68,0.2)`, background: \"rgba(239,68,68,0.06)\", color: tk.red, fontSize: 12, cursor: \"pointer\", fontFamily: \"inherit\" }}>\n                      <X size={11}/>\n                    </button>\n                  </div>\n                </div>\n              );\n            })}\n          </div>\n        )}\n      </motion.div>\n\n      {/* DNS instructions */}\n      {customDomains.length > 0 && (\n        <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}\n          style={{ borderRadius: 18, background: isDark ? \"#120820\" : \"#F5F3FF\", border: `1px solid rgba(107,53,232,0.15)`, padding: \"20px 24px\", marginBottom: 16 }}>\n          <div style={{ display: \"flex\", gap: 10, marginBottom: 16 }}>\n            <AlertCircle size={16} color={V.v400} style={{ flexShrink: 0, marginTop: 1 }}/>\n            <div>\n              <p style={{ fontSize: 14, fontWeight: 700, color: tk.text, margin: \"0 0 4px\" }}>Configure your DNS records</p>\n              <p style={{ fontSize: 13, color: tk.muted, margin: 0 }}>Add these records at your domain registrar (Namecheap, GoDaddy, Whogohost, etc.)</p>\n            </div>\n          </div>\n\n          <div style={{ display: \"flex\", flexDirection: \"column\", gap: 10 }}>\n            {[\n              { type: \"A\", name: \"@\", value: VERCEL_IP, purpose: \"Root domain (yourdomain.com)\" },\n              { type: \"CNAME\", name: \"www\", value: VERCEL_CNAME, purpose: \"WWW version\" },\n            ].map(rec => (\n              <div key={rec.type} style={{ borderRadius: 10, border: `1px solid ${tk.border}`, background: tk.card, overflow: \"hidden\" }}>\n                <div style={{ display: \"grid\", gridTemplateColumns: \"60px 80px 1fr auto\", gap: 0, fontSize: 12 }}>\n                  {[\n                    { label: \"TYPE\",    val: rec.type  },\n                    { label: \"NAME\",    val: rec.name  },\n                    { label: \"VALUE\",   val: rec.value },\n                    { label: \"\",        val: \"copy\"    },\n                  ].map((cell, ci) => (\n                    <div key={ci} style={{ padding: \"12px 14px\", borderRight: ci < 3 ? `1px solid ${tk.border}` : \"none\" }}>\n                      {ci === 0 && <p style={{ fontSize: 10, color: tk.muted, margin: \"0 0 3px\", fontWeight: 700, textTransform: \"uppercase\" }}>Type</p>}\n                      {ci === 1 && <p style={{ fontSize: 10, color: tk.muted, margin: \"0 0 3px\", fontWeight: 700, textTransform: \"uppercase\" }}>Name</p>}\n                      {ci === 2 && <p style={{ fontSize: 10, color: tk.muted, margin: \"0 0 3px\", fontWeight: 700, textTransform: \"uppercase\" }}>Value</p>}\n                      {ci === 3 && <div style={{ display: \"flex\", alignItems: \"center\", height: \"100%\" }}>\n                        <button onClick={() => copy(rec.value)} style={{ background: \"none\", border: \"none\", cursor: \"pointer\", color: V.v400, display: \"flex\", alignItems: \"center\", gap: 4, fontSize: 11, fontWeight: 600, fontFamily: \"inherit\" }}>\n                          <Copy size={11}/> Copy\n                        </button>\n                      </div>}\n                      {ci < 3 && <p style={{ fontSize: 12, fontWeight: ci === 2 ? 500 : 700, color: tk.text, margin: 0, fontFamily: ci === 2 ? \"monospace\" : \"inherit\", wordBreak: \"break-all\" }}>{cell.val}</p>}\n                    </div>\n                  ))}\n                </div>\n                <div style={{ padding: \"6px 14px 8px\", borderTop: `1px solid ${tk.border}`, background: tk.faint }}>\n                  <p style={{ fontSize: 11, color: tk.muted, margin: 0 }}>{rec.purpose} · DNS changes can take up to 48 hours</p>\n                </div>\n              </div>\n            ))}\n          </div>\n        </motion.div>\n      )}\n\n      {/* Domain search / purchase */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}\n        style={{ borderRadius: 18, background: tk.card, border: `1px solid ${tk.border}`, padding: \"20px 24px\" }}>\n        <h3 style={{ fontSize: 15, fontWeight: 800, color: tk.text, margin: \"0 0 4px\" }}>Find a Domain</h3>\n        <p style={{ fontSize: 13, color: tk.muted, margin: \"0 0 16px\" }}>Search for available domains and purchase through our partner registrars.</p>\n\n        <div style={{ display: \"flex\", gap: 10, marginBottom: 16 }}>\n          <div style={{ flex: 1, display: \"flex\", alignItems: \"center\", gap: 8, padding: \"11px 14px\", borderRadius: 11, border: `1px solid ${tk.border}`, background: isDark ? \"rgba(255,255,255,0.04)\" : \"#f9fafb\" }}>\n            <Search size={14} color={tk.muted}/>\n            <input value={domainSearch} onChange={e => setDomainSearch(e.target.value)}\n              onKeyDown={e => e.key === \"Enter\" && searchDomains()}\n              placeholder=\"Search for a domain name...\" \n              style={{ flex: 1, background: \"transparent\", border: \"none\", outline: \"none\", fontSize: 14, color: tk.text, fontFamily: \"inherit\" }}/>\n          </div>\n          <button onClick={searchDomains} disabled={searching || !domainSearch}\n            style={{ padding: \"11px 20px\", borderRadius: 11, background: `linear-gradient(135deg,${V.v500},${V.v400})`, border: \"none\", color: \"#fff\", fontSize: 13, fontWeight: 700, cursor: searching||!domainSearch ? \"not-allowed\" : \"pointer\", fontFamily: \"inherit\", display: \"flex\", alignItems: \"center\", gap: 6, opacity: !domainSearch ? 0.5 : 1 }}>\n            {searching ? <Loader2 size={13} style={{ animation: \"spin 1s linear infinite\" }}/> : <Search size={13}/>}\n            Search\n          </button>\n        </div>\n\n        {searchResults.length > 0 && (\n          <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n            {searchResults.map(r => (\n              <div key={r.domain} style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"12px 16px\", borderRadius: 11, border: `1px solid ${r.available ? tk.green+\"30\" : tk.border}`, background: r.available ? `${tk.green}06` : tk.faint }}>\n                <div style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n                  {r.available\n                    ? <Check size={15} color={tk.green}/>\n                    : <X size={15} color={tk.muted}/>\n                  }\n                  <div>\n                    <p style={{ fontSize: 14, fontWeight: 700, color: r.available ? tk.text : tk.muted, margin: 0 }}>{r.domain}</p>\n                    <p style={{ fontSize: 11, color: r.available ? tk.green : tk.muted, margin: 0 }}>\n                      {r.available ? \"Available\" : \"Taken\"}\n                    </p>\n                  </div>\n                </div>\n                <div style={{ display: \"flex\", gap: 8, alignItems: \"center\" }}>\n                  {r.available && <span style={{ fontSize: 13, fontWeight: 700, color: tk.text }}>{r.price}</span>}\n                  {r.available && (\n                    <a href={`${r.registrar}/domain-registration?domain=${r.domain}`} target=\"_blank\" rel=\"noopener noreferrer\"\n                      style={{ padding: \"7px 16px\", borderRadius: 8, background: `linear-gradient(135deg,${V.v500},${V.v400})`, color: \"#fff\", fontSize: 12, fontWeight: 700, textDecoration: \"none\" }}>\n                      Buy →\n                    </a>\n                  )}\n                </div>\n              </div>\n            ))}\n            <p style={{ fontSize: 12, color: tk.muted, textAlign: \"center\", marginTop: 8 }}>\n              Domains purchased through <strong>Whogohost</strong> — Nigeria's leading registrar.\n              After purchase, add it above to connect to your store.\n            </p>\n          </div>\n        )}\n      </motion.div>\n\n      <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/stores/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Store, Plus, ExternalLink, Edit2, Trash2, Globe, Zap, AlertCircle, Loader2, X, Check, Copy } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\" };\n\nfunction StoreModal({ store, onClose, t, isDark, onSuccess }: any) {\n  const isEdit = !!store;\n  const [form, setForm] = useState({\n    name:        store?.name        || \"\",\n    description: store?.description || \"\",\n    slug:        store?.slug        || \"\",\n    currency:    store?.currency    || \"NGN\",\n    brandColor:  store?.brandColor  || \"#6B35E8\",\n    theme:       store?.theme       || \"classic\",\n  });\n\n  const inp = { padding: \"10px 14px\", borderRadius: 10, border: `1px solid ${t.border}`, background: isDark ? \"rgba(255,255,255,0.04)\" : \"#f9fafb\", color: t.text, fontSize: 13, outline: \"none\", width: \"100%\" } as any;\n\n  const mut = useMutation({\n    mutationFn: async () => {\n      if (isEdit) return api.put(`/stores/${store.id}`, form);\n      return api.post(\"/stores\", form);\n    },\n    onSuccess: () => { toast.success(isEdit ? \"Store updated\" : \"Store created!\"); onSuccess(); onClose(); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed\"),\n  });\n\n  const THEMES: string[] = []; // Managed at /dashboard/customize\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-center justify-center p-4\"\n      style={{ background: \"rgba(0,0,0,0.6)\", backdropFilter: \"blur(8px)\" }}\n      onClick={e => e.target === e.currentTarget && onClose()}>\n      <motion.div initial={{ opacity: 0, scale: 0.95, y: 16 }} animate={{ opacity: 1, scale: 1, y: 0 }}\n        className=\"w-full max-w-lg rounded-3xl overflow-hidden\"\n        style={{ background: isDark ? \"#181230\" : \"#fff\", border: `1px solid ${t.border}` }}>\n        <div className=\"flex items-center justify-between px-6 py-4\" style={{ borderBottom: `1px solid ${t.border}` }}>\n          <h2 style={{ fontSize: 16, fontWeight: 800, color: t.text }}>{isEdit ? \"Edit Store\" : \"Create Store\"}</h2>\n          <button onClick={onClose} style={{ color: t.muted }}><X size={18} /></button>\n        </div>\n        <div className=\"p-6 space-y-4 max-h-[70vh] overflow-y-auto\">\n          <div>\n            <label style={{ fontSize: 12, fontWeight: 600, color: t.muted, display: \"block\", marginBottom: 6 }}>Store Name *</label>\n            <input style={inp} value={form.name} onChange={e => { setForm(f => ({ ...f, name: e.target.value, slug: !isEdit ? e.target.value.toLowerCase().replace(/[^a-z0-9]/g, \"-\").replace(/-+/g, \"-\") : f.slug })); }} placeholder=\"e.g. Amaka's Hair Store\" />\n          </div>\n          <div>\n            <label style={{ fontSize: 12, fontWeight: 600, color: t.muted, display: \"block\", marginBottom: 6 }}>Store URL Slug *</label>\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 0 }}>\n              <span style={{ padding: \"10px 12px\", borderRadius: \"10px 0 0 10px\", border: `1px solid ${t.border}`, borderRight: \"none\", background: isDark ? \"rgba(255,255,255,0.02)\" : \"#f1f5f9\", fontSize: 12, color: t.muted, whiteSpace: \"nowrap\" }}>{(form.slug||\"your-store\")}.droposhq.com</span>\n              <input style={{ ...inp, borderRadius: \"0 10px 10px 0\", borderLeft: \"none\" } as any} value={form.slug} onChange={e => setForm(f => ({ ...f, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, \"\") }))} placeholder=\"my-store\" />\n            </div>\n          </div>\n          <div>\n            <label style={{ fontSize: 12, fontWeight: 600, color: t.muted, display: \"block\", marginBottom: 6 }}>Description</label>\n            <textarea style={{ ...inp, resize: \"none\" } as any} rows={2} value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} placeholder=\"What do you sell?\" />\n          </div>\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label style={{ fontSize: 12, fontWeight: 600, color: t.muted, display: \"block\", marginBottom: 6 }}>Currency</label>\n              <select style={{ ...inp, cursor: \"pointer\" } as any} value={form.currency} onChange={e => setForm(f => ({ ...f, currency: e.target.value }))}>\n                <option value=\"NGN\">NGN (₦)</option>\n                <option value=\"USD\">USD ($)</option>\n                <option value=\"GBP\">GBP (£)</option>\n                <option value=\"GHS\">GHS (₵)</option>\n                <option value=\"KES\">KES (KSh)</option>\n              </select>\n            </div>\n            <div>\n              <label style={{ fontSize: 12, fontWeight: 600, color: t.muted, display: \"block\", marginBottom: 6 }}>Brand Color</label>\n              <div style={{ display: \"flex\", gap: 6, alignItems: \"center\" }}>\n                <input type=\"color\" value={form.brandColor} onChange={e => setForm(f => ({ ...f, brandColor: e.target.value }))}\n                  style={{ width: 40, height: 38, borderRadius: 8, border: `1px solid ${t.border}`, background: \"none\", cursor: \"pointer\", padding: 2 }} />\n                <input style={{ ...inp, flex: 1 } as any} value={form.brandColor} onChange={e => setForm(f => ({ ...f, brandColor: e.target.value }))} placeholder=\"#6B35E8\" />\n              </div>\n            </div>\n          </div>\n          <div>\n            <label style={{ fontSize: 12, fontWeight: 600, color: t.muted, display: \"block\", marginBottom: 8 }}>Theme</label>\n            <div className=\"grid grid-cols-3 gap-2\">\n              {THEMES.map(th => (\n                <button key={th} onClick={() => setForm(f => ({ ...f, theme: th }))} type=\"button\"\n                  style={{ padding: \"8px 10px\", borderRadius: 10, border: `1px solid ${form.theme === th ? V.v500 : t.border}`, background: form.theme === th ? `${V.v500}14` : \"transparent\", color: form.theme === th ? V.v400 : t.muted, fontSize: 11, fontWeight: 600, cursor: \"pointer\", textTransform: \"capitalize\" }}>\n                  {th.replace(\"-\", \" \")}\n                </button>\n              ))}\n            </div>\n          </div>\n        </div>\n        <div className=\"px-6 py-4 flex gap-3 justify-end\" style={{ borderTop: `1px solid ${t.border}` }}>\n          <button onClick={onClose} style={{ padding: \"10px 20px\", borderRadius: 10, border: `1px solid ${t.border}`, background: \"transparent\", color: t.muted, fontSize: 13, fontWeight: 600, cursor: \"pointer\" }}>Cancel</button>\n          <button onClick={() => mut.mutate()} disabled={mut.isPending || !form.name || !form.slug}\n            style={{ padding: \"10px 24px\", borderRadius: 10, border: \"none\", background: `linear-gradient(135deg,${V.v500},#3D1C8A)`, color: \"#fff\", fontSize: 13, fontWeight: 700, cursor: \"pointer\", display: \"flex\", alignItems: \"center\", gap: 6, opacity: (!form.name || !form.slug) ? 0.5 : 1 }}>\n            {mut.isPending ? <><Loader2 size={13} className=\"animate-spin\" /> Saving…</> : <><Check size={13} /> {isEdit ? \"Save\" : \"Create Store\"}</>}\n          </button>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\nexport default function StoresPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const qc = useQueryClient();\n  \n  const t = {\n    card:   isDark ? \"#181230\"                : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text:   isDark ? \"#fff\"                   : \"#0D0918\",\n    muted:  isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\",\n  };\n\n  const [modal, setModal] = useState<null | \"create\" | any>(null);\n\n  const { data, isLoading, error, refetch } = useQuery({\n    queryKey: [\"my-stores\"],\n    queryFn: () => api.get(\"/stores\").then(r => r.data.data),\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: (id: string) => api.delete(`/stores/${id}`),\n    onSuccess: () => { toast.success(\"Store deleted\"); refetch(); },\n    onError: () => toast.error(\"Failed to delete store\"),\n  });\n\n  const stores: any[] = Array.isArray(data) ? data : [];\n\n  const handleSuccess = () => { refetch();  };\n\n  const copyLink = (slug: string) => {\n    navigator.clipboard.writeText(`https://droposhq.com/store/${slug}`);\n    toast.success(\"Link copied!\");\n  };\n\n  return (\n    <div style={{ maxWidth: 1400, margin: \"0 auto\" }}>\n      <div className=\"flex items-start justify-between mb-6\">\n        <div>\n          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: \"-0.03em\", color: t.text }}>My Stores</h1>\n          <p style={{ fontSize: 13, color: t.muted, marginTop: 4 }}>{stores.length > 0 ? `${stores.length} store${stores.length !== 1 ? \"s\" : \"\"} active` : \"Create your first store to start selling\"}</p>\n        </div>\n        <button onClick={() => setModal(\"create\")}\n          style={{ display: \"flex\", alignItems: \"center\", gap: 7, padding: \"10px 18px\", borderRadius: 12, border: \"none\", cursor: \"pointer\", background: `linear-gradient(135deg,${V.v500},#3D1C8A)`, color: \"#fff\", fontSize: 13, fontWeight: 700, boxShadow: \"0 4px 16px rgba(107,53,232,0.35)\" }}>\n          <Plus size={14} /> Create Store\n        </button>\n      </div>\n\n      {isLoading ? (\n        <div style={{ padding: 60, textAlign: \"center\" }}>\n          <Loader2 size={28} className=\"animate-spin\" style={{ margin: \"0 auto\", color: V.v400, display: \"block\" }} />\n          <p style={{ color: t.muted, fontSize: 13, marginTop: 12 }}>Loading stores…</p>\n        </div>\n      ) : error ? (\n        <div style={{ padding: 60, textAlign: \"center\", borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n          <AlertCircle size={28} style={{ margin: \"0 auto 10px\", color: \"#EF4444\", display: \"block\" }} />\n          <p style={{ color: t.text, fontWeight: 700 }}>Could not load stores</p>\n          <p style={{ color: t.muted, fontSize: 13, marginTop: 4 }}>Check your connection and try again</p>\n        </div>\n      ) : stores.length === 0 ? (\n        <div style={{ padding: \"60px 24px\", textAlign: \"center\", borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n          <div style={{ width: 72, height: 72, borderRadius: 22, background: \"rgba(6,182,212,0.1)\", border: \"1px solid rgba(6,182,212,0.2)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", margin: \"0 auto 16px\" }}>\n            <Store size={32} color=\"#06B6D4\" />\n          </div>\n          <h3 style={{ fontSize: 17, fontWeight: 800, color: t.text, marginBottom: 8 }}>No stores yet</h3>\n          <p style={{ fontSize: 13, color: t.muted, marginBottom: 24, maxWidth: 360, margin: \"0 auto 24px\" }}>\n            Create your first store and you can start selling in under 60 seconds. KIRO will help you set it up.\n          </p>\n          <button onClick={() => setModal(\"create\")}\n            style={{ display: \"inline-flex\", alignItems: \"center\", gap: 7, padding: \"12px 24px\", borderRadius: 12, border: \"none\", cursor: \"pointer\", background: `linear-gradient(135deg,${V.v500},#3D1C8A)`, color: \"#fff\", fontSize: 13, fontWeight: 700 }}>\n            <Plus size={14} /> Create your first store\n          </button>\n        </div>\n      ) : (\n        <div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          {stores.map((store: any, i: number) => (\n            <motion.div key={store.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}\n              style={{ borderRadius: 18, background: t.card, border: `1px solid ${t.border}`, overflow: \"hidden\" }}>\n              {/* Header */}\n              <div style={{ padding: \"20px 20px 16px\", borderBottom: `1px solid ${t.border}` }}>\n                <div style={{ display: \"flex\", alignItems: \"flex-start\", justifyContent: \"space-between\", marginBottom: 12 }}>\n                  <div style={{ width: 44, height: 44, borderRadius: 13, background: `${store.brandColor || V.v500}18`, border: `1px solid ${store.brandColor || V.v500}25`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                    <Store size={20} style={{ color: store.brandColor || V.v400 }} />\n                  </div>\n                  <div style={{ display: \"flex\", gap: 4 }}>\n                    <button onClick={() => setModal(store)}\n                      style={{ padding: 7, borderRadius: 8, border: `1px solid ${t.border}`, background: \"transparent\", color: t.muted, cursor: \"pointer\", display: \"flex\" }}>\n                      <Edit2 size={13} />\n                    </button>\n                    <button onClick={() => { if (confirm(`Delete \"${store.name}\"? This cannot be undone.`)) deleteMut.mutate(store.id); }}\n                      style={{ padding: 7, borderRadius: 8, border: \"1px solid rgba(239,68,68,0.2)\", background: \"transparent\", color: \"#EF4444\", cursor: \"pointer\", display: \"flex\" }}>\n                      <Trash2 size={13} />\n                    </button>\n                  </div>\n                </div>\n                <h3 style={{ fontSize: 15, fontWeight: 800, color: t.text, marginBottom: 4 }}>{store.name}</h3>\n                {store.description && <p style={{ fontSize: 12, color: t.muted, lineHeight: 1.5 }}>{store.description}</p>}\n              </div>\n              {/* Stats */}\n              <div className=\"grid grid-cols-2\" style={{ padding: \"12px 20px\", gap: 12 }}>\n                {[\n                  { label: \"Products\", value: store._count?.products ?? store.productCount ?? \"—\" },\n                  { label: \"Orders\", value: store._count?.orders ?? store.orderCount ?? \"—\" },\n                ].map(s => (\n                  <div key={s.label}>\n                    <p style={{ fontSize: 11, color: t.muted }}>{s.label}</p>\n                    <p style={{ fontSize: 18, fontWeight: 900, color: t.text }}>{s.value}</p>\n                  </div>\n                ))}\n              </div>\n              {/* Actions */}\n              <div style={{ padding: \"0 16px 16px\", display: \"flex\", gap: 8 }}>\n                <Link href={`/store/${store.slug}`} target=\"_blank\"\n                  className=\"flex items-center gap-1.5 flex-1 justify-center py-2.5 rounded-xl text-xs font-bold transition-all hover:opacity-80\"\n                  style={{ border: `1px solid ${t.border}`, color: t.muted, background: \"transparent\" }}>\n                  <ExternalLink size={12} /> View Store\n                </Link>\n                <button onClick={() => copyLink(store.slug)}\n                  className=\"flex items-center gap-1.5 flex-1 justify-center py-2.5 rounded-xl text-xs font-bold transition-all hover:opacity-80\"\n                  style={{ border: `1px solid ${store.brandColor || V.v500}40`, color: store.brandColor || V.v400, background: `${store.brandColor || V.v500}08` }}>\n                  <Copy size={12} /> Copy Link\n                </button>\n              </div>\n            </motion.div>\n          ))}\n        </div>\n      )}\n\n      <AnimatePresence>\n        {modal && (\n          <StoreModal\n            store={modal === \"create\" ? null : modal}\n            onClose={() => setModal(null)}\n            t={t} isDark={isDark}\n            onSuccess={handleSuccess}\n          />\n        )}\n      </AnimatePresence>\n    </div>\n  );\n}\n","backend/src/routes/store.routes.ts":"// backend/src/routes/store.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  createStore, getMyStores, getStore,\n  updateStore, deleteStore, updateDomain,\n  getPublicStore,\n} from \"../controllers/store.controller\";\nimport {\n  createFlashSale, getFlashSales, updateFlashSale,\n  deleteFlashSale, getActiveFlashSales,\n} from \"../controllers/returns.controller\";\n\nconst router = Router();\n\n// Public\nrouter.get(\"/public/:slug\", getPublicStore);\n\n// Authenticated\nrouter.post(\"/\",            authenticate, createStore);\nrouter.get(\"/\",             authenticate, getMyStores);\nrouter.get(\"/:id\",          authenticate, getStore);\nrouter.put(\"/:id\",          authenticate, updateStore);\nrouter.patch(\"/:id\",        authenticate, updateStore);\nrouter.delete(\"/:id\",       authenticate, deleteStore);\nrouter.patch(\"/:id/domain\", authenticate, updateDomain);\n\n// Flash Sales — frontend calls /stores/:id/flash-sales\nrouter.get(\"/:id/flash-sales/active\", getActiveFlashSales);\nrouter.get(\"/:id/flash-sales\",        authenticate, getFlashSales);\nrouter.post(\"/:id/flash-sales\",       authenticate, createFlashSale);\nrouter.patch(\"/:id/flash-sales/:saleId\", authenticate, updateFlashSale);\nrouter.delete(\"/:id/flash-sales/:saleId\", authenticate, deleteFlashSale);\n\nexport default router;\n// Custom domain lookup — used by Next.js middleware\nrouter.get(\"/domain/:hostname\", async (req: any, res: any) => {\n  try {\n    const { hostname } = req.params;\n    const { prisma } = await import(\"../config/database\");\n    const store = await (prisma as any).store.findFirst({\n      where: {\n        OR: [\n          { customDomain: hostname },\n          { customDomains: { has: hostname } },\n        ],\n        isActive: true,\n      },\n      select: { slug: true, id: true, name: true },\n    });\n    if (!store) return res.status(404).json({ success: false });\n    return res.json({ success: true, data: store });\n  } catch {\n    return res.status(500).json({ success: false });\n  }\n});\n"};
